static void render_status(void) {
    oled_write_P(PSTR("Sofle Pico\nv3.04\n~~~~~~~~~\n"), false);

    os_variant_t detected_os = detected_host_os();
    oled_write_P(PSTR("\nOS: "), false);
    switch (detected_os) {
        case OS_MACOS:
            oled_write_P(PSTR("MacOS"), false);
            break;
        case OS_IOS:
            oled_write_P(PSTR("iOS  "), false);
            break;
        case OS_WINDOWS:
            oled_write_P(PSTR("Win  "), false);
            break;
        case OS_LINUX:
            oled_write_P(PSTR("Linux"), false);
            break;
        case OS_UNSURE:
            oled_write_P(PSTR("Unk  "), false);
            break;
    }

    const char* effect_name = rgb_matrix_get_mode_name(rgb_matrix_get_mode());
    oled_write_P(PSTR("\nRGB: "), false);
    oled_write_P(PSTR(effect_name), false);

    led_t led_state = host_keyboard_led_state();
    oled_write_P(PSTR("\n\nLock: "), false);
    oled_write_P(led_state.caps_lock ? PSTR("C") : PSTR("_"), false);
    oled_write_P(led_state.num_lock ? PSTR("N") : PSTR("_"), false);
    oled_write_P(led_state.scroll_lock ? PSTR("S") : PSTR("_"), false);

    oled_write_P(PSTR("\nCaps: "), false);
    if (led_state.caps_lock) {
        oled_write_P(PSTR("lock"), false);
    } else if (is_caps_word_on()) {
        oled_write_P(PSTR("word"), false);
    } else {
        oled_write_P(PSTR("off "), false);
    }

    oled_write_P(PSTR("\n"), false);
    switch (get_highest_layer(layer_state)) {
        case _QWERTY:
            oled_write_P(PSTR("Base "), false);
            break;
        case _LOWER:
            oled_write_P(PSTR("Lower"), false);
            break;
        default:
            oled_write_P(PSTR("Unk  "), false);
            break;
    }
}

bool oled_task_user(void) {
    static bool finished_logo = false;
    if ((timer_elapsed(startup_timer) < OLED_LOGO_TIMEOUT) && !finished_logo) {
        // Display the logo for 5 seconds on boot.
        if (is_keyboard_master()) {
            render_logo();
            // 10 Chars per line. Set cursor used to simplify line wraps.
            oled_set_cursor(0, 12);
            oled_write_P(PSTR("v1"), false);
            oled_set_cursor(0, 13);
            oled_write_P(PSTR("2025-11-06"), false);
            oled_set_cursor(0, 14);
            oled_write_P(PSTR("by:github/"), false);
            oled_set_cursor(0, 15);
            oled_write_P(PSTR("fishjord"), false);
        } else {
            render_qmk_logo();
        }
    } else {
        // Display the current keyboard state.
        if (!finished_logo) {
            finished_logo = true;
            // Clears the OLED.
            oled_clear();
        }
        if (is_keyboard_master()) {
            render_status(); // Renders the current keyboard state (layer, lock, caps, scroll, etc)
        } else {
            render_logo();
        }
    }
    return false;
}
